import { registerAsset } from '@projexlight/sdk-asset';

const { asset_id } = await registerAsset({
  tenant_id: req.auth.tenant_id,
  device_uuid: 'dev-9f2c',
  model: 'humanoid-v2',
  display_name: 'Cell-A Picker',
  components: [
    { kind: 'arm', name: 'left-arm', sensors: [
      { kind: 'joint_angle', unit: 'deg', min_value: -180, max_value: 180, sample_rate_hz: 100 },
      { kind: 'force', unit: 'N', sample_rate_hz: 50 },
    ], children: [
      { kind: 'hand', sensors: [{ kind: 'temperature', unit: 'C' }] },
    ] },
  ],
});

import { getTwin } from '@projexlight/sdk-asset';

const twin = await getTwin(assetId);
if (!twin) return reply.code(404).send({ error: 'asset_not_found' });
for (const root of twin.components) {
  console.log(root.kind, root.sensors.map((s) => s.kind), root.children.length);
}

import { ingestReadings, queryReadings } from '@projexlight/sdk-asset';

await ingestReadings([
  { sensor_id: sensorId, asset_id: assetId, tenant_id: tenantId, value: 12.4, quality: 'ok' },
  { sensor_id: sensorId, asset_id: assetId, tenant_id: tenantId, value: 12.9 },
]);

const hourly = await queryReadings(assetId, {
  sensor_id: sensorId,
  from: '2026-07-23T00:00:00Z',
  bucket: 'hour',
});

import { runSensorRollup, startSensorRollupJob } from '@projexlight/sdk-asset';

// one-off idempotent rebuild of a specific window
const result = await runSensorRollup({
  from: '2026-07-20T00:00:00Z',
  to: '2026-07-21T00:00:00Z',
});

// or start the periodic trailing-window catch-up loop at boot
const stop = startSensorRollupJob();
